"use strict";(self.webpackChunkhudi=self.webpackChunkhudi||[]).push([[38209],{18650:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>o,default:()=>d,frontMatter:()=>i,metadata:()=>a,toc:()=>c});var a=n(99190),s=n(74848),r=n(28453);const i={title:"What is Incremental ETL on a Data Lake?",excerpt:"Incremental ETL is a pipeline pattern that processes only the data that changed since the last run. This post explains how it works, what the storage layer must provide, and how it compares to batch and stream processing.",description:"Incremental ETL processes only changed data instead of recomputing entire tables. Learn how it works on a data lake and how Apache Hudi enables it.",authors:["vinoth-chandar"],category:"how-to",image:"/assets/images/blog/incr-processing/image7.png",tags:["incremental processing","etl","streaming","data lakehouse","cdc"]},o=void 0,l={authorsImageUrls:[void 0]},c=[{value:"The Problem with Full Recomputation",id:"the-problem-with-full-recomputation",level:2},{value:"What Makes ETL &quot;Incremental&quot;",id:"what-makes-etl-incremental",level:2},{value:"What the Storage Layer Must Provide",id:"what-the-storage-layer-must-provide",level:2},{value:"Frequent Table Maintenance Becomes the Norm",id:"frequent-table-maintenance-becomes-the-norm",level:3},{value:"Incremental ETL vs. Stream Processing",id:"incremental-etl-vs-stream-processing",level:2},{value:"A Concrete Pipeline Walkthrough",id:"a-concrete-pipeline-walkthrough",level:2},{value:"A Brief History: Pioneered at Uber",id:"a-brief-history-pioneered-at-uber",level:2},{value:"Conclusion",id:"conclusion",level:2},{value:"FAQ",id:"faq",level:2}];function h(e){const t={a:"a",code:"code",em:"em",h2:"h2",h3:"h3",img:"img",li:"li",ol:"ol",p:"p",pre:"pre",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,r.R)(),...e.components},{PostFAQ:a}=t;return a||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("PostFAQ",!0),(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.p,{children:"Incremental ETL is a pipeline pattern that processes only the data that changed since the last run, instead of recomputing entire tables or partitions on every execution. Each run of an incremental pipeline consumes a delta \u2014 the records inserted, updated, or deleted after a known checkpoint \u2014 applies its transformation logic to just that delta, and merges the results into the target table. The pipeline's work is proportional to how much the data changed, not how large the tables have grown."}),"\n",(0,s.jsx)(t.p,{children:"That distinction matters because most data pipelines today still run as full-recompute batch jobs: every night (or every hour), they re-scan source tables end to end and rewrite the derived tables downstream, even when only a tiny fraction of the rows actually changed. As data volumes grow, that recomputation gets slower and more expensive at exactly the moment businesses are asking for fresher data."}),"\n",(0,s.jsxs)(t.p,{children:["Incremental ETL occupies the middle ground between classic batch processing and full stream processing. It keeps the familiar economics and tooling of batch \u2014 scheduled jobs, SQL or DataFrame transformations, cheap ",(0,s.jsx)(t.a,{href:"/blog/2024/07/11/what-is-a-data-lakehouse",children:"data lakehouse"})," storage \u2014 while borrowing the core idea of stream processing: treat data as a continuous flow of changes, and process each change roughly once."]}),"\n",(0,s.jsx)(t.h2,{id:"the-problem-with-full-recomputation",children:"The Problem with Full Recomputation"}),"\n",(0,s.jsx)(t.p,{children:"Consider a typical medallion-style warehouse or lakehouse: raw data lands in bronze tables, gets cleaned into silver tables, and is aggregated into gold tables for reporting. In a full-recompute design, each layer is rebuilt by scanning its inputs wholesale. Three problems compound as the tables grow:"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Cost."})," A daily job that scans a multi-terabyte fact table to pick up one day's worth of changes does orders of magnitude more I/O and compute than the size of the change justifies. Joins are the worst offenders: rewriting a large joined table means re-shuffling both sides in full, every run. Organizations routinely spend a large share of their data platform budget on pipelines that mostly reprocess data they already processed yesterday."]}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Latency."})," If rebuilding a table takes four hours, the data in it can never be fresher than four hours plus the scheduling interval. Teams respond by running the job less often (making data staler) or throwing more compute at it (making it more expensive). Neither addresses the root cause: the work grows with table size rather than change size."]}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Missed SLAs and cascading delays."})," Derived pipelines form DAGs. When an upstream full-recompute job runs long, every downstream job either starts late or reads stale inputs. Late-arriving data makes this worse: when records for an old partition show up, the whole partition \u2014 and every downstream partition derived from it \u2014 must be recomputed, silently blowing through freshness SLAs."]}),"\n"]}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:'Stream processing solves the latency problem but replaces batch\'s cost profile with a different one: always-on clusters, state stores to manage, and a second storage system (typically a log store like Kafka) holding another copy of the data. For the large class of pipelines where "fresh within a few minutes" is sufficient, that operational overhead buys latency headroom no one uses.'}),"\n",(0,s.jsx)(t.h2,{id:"what-makes-etl-incremental",children:'What Makes ETL "Incremental"'}),"\n",(0,s.jsx)(t.p,{children:"An ETL pipeline is incremental when both its input and its output are expressed as changes:"}),"\n",(0,s.jsxs)(t.ol,{children:["\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Change streams in."})," Instead of scanning the full source table, the pipeline asks the storage layer a question a plain file listing cannot answer: ",(0,s.jsx)(t.em,{children:'"give me all records that changed since commit X."'})," The result is a delta \u2014 new inserts, the latest values of updated records, and deletes \u2014 along with a new checkpoint to resume from next run."]}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Incremental writes out."})," Instead of rewriting the target table, the pipeline applies its transformed delta using record-level operations \u2014 upserts and deletes \u2014 so only the affected file groups are rewritten. Crucially, this makes the ",(0,s.jsx)(t.em,{children:"output"})," table itself an incremental source: the next pipeline in the DAG can consume its changes the same way."]}),"\n"]}),"\n"]}),"\n",(0,s.jsxs)(t.p,{children:['Because deltas flow in and deltas flow out, the pattern composes. A chain of incremental pipelines behaves like a topology of stream processors \u2014 each stage consuming a change stream and emitting one \u2014 except the "streams" are ordinary tables on cheap cloud storage, queryable by any engine at any time. This is the ',(0,s.jsx)(t.a,{href:"/blog/2020/08/18/hudi-incremental-processing-on-data-lakes",children:"duality between change logs and tables"})," that stream processing literature has long described, realized directly on the data lake."]}),"\n",(0,s.jsxs)(t.p,{children:["The efficiency win is easy to see with numbers. If a 10 TB fact table receives 50 GB of changes per hour, an hourly incremental pipeline processes 50 GB per run instead of 10 TB \u2014 a 200x reduction in data scanned, while ",(0,s.jsx)(t.em,{children:"improving"})," freshness from daily to hourly."]}),"\n",(0,s.jsx)(t.h2,{id:"what-the-storage-layer-must-provide",children:"What the Storage Layer Must Provide"}),"\n",(0,s.jsx)(t.p,{children:"Incremental ETL is not primarily a compute-engine feature; it is a storage contract. Plain files in cloud storage \u2014 even columnar formats like Parquet \u2014 cannot tell a consumer what changed, and cannot accept record-level updates without rewriting whole files or partitions. Open table formats close this gap to varying degrees. Concretely, the storage layer must provide three primitives:"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Record-level change retrieval."}),' The table must be able to answer "what changed between time T1 and T2" efficiently, without scanning everything. This comes in two flavors: ',(0,s.jsx)(t.em,{children:"incremental queries"}),", which return the latest value of each changed record (ideal for driving downstream upserts), and ",(0,s.jsx)(t.em,{children:"CDC queries"}),", which return before/after images of every change (needed when the transformation must see each individual mutation). Apache Hudi supports ",(0,s.jsx)(t.a,{href:"/docs/sql_queries#incremental-query",children:"both query types"})," on Copy-on-Write and Merge-on-Read tables."]}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Upserts and deletes to apply changes."})," Producing a delta is only useful if the next table can absorb it cheaply. That requires primary keys and indexes to locate which files contain the affected records, so a small change touches a small amount of storage. Hudi's ",(0,s.jsx)(t.a,{href:"/docs/write_operations",children:"write operations"})," are built around indexed upserts and deletes, with merge modes to handle out-of-order and late-arriving data correctly."]}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Ordering and commit points."}),' Consumers need a reliable notion of "where I left off." Hudi\'s ',(0,s.jsx)(t.a,{href:"/docs/timeline",children:"timeline"})," records every action on the table as an atomically committed instant; incremental queries use commit completion times to define exact, repeatable change windows, and checkpoints are managed automatically by tools like Hudi Streamer's incremental sources. Hudi additionally tracks record-level metadata (commit time and sequence number on every record), so change history survives background operations like compaction and clustering rather than depending on which snapshots happen to be retained."]}),"\n"]}),"\n"]}),"\n",(0,s.jsxs)(t.p,{children:["These primitives \u2014 upsert and incremental consumption \u2014 are exactly the pair that defines the pattern: with them, you can maintain one table from a change stream, then derive another table from ",(0,s.jsx)(t.em,{children:"its"})," change stream, end to end. The ",(0,s.jsx)(t.a,{href:"/docs/use_cases",children:"use cases documentation"})," covers how this plays out across ingestion, warehouse offload, and derived pipelines."]}),"\n",(0,s.jsx)(t.h3,{id:"frequent-table-maintenance-becomes-the-norm",children:"Frequent Table Maintenance Becomes the Norm"}),"\n",(0,s.jsxs)(t.p,{children:["There is a fourth requirement that follows directly from the first three: the format must be designed for frequent table maintenance, because incremental processing fundamentally increases how often the table is written. A table that once absorbed one nightly batch now commits every few minutes \u2014 producing small files, accumulating deltas in log files, and continuously churning the storage layout. At that write frequency, maintenance work \u2014 ",(0,s.jsx)(t.a,{href:"/docs/compaction",children:"compaction"}),", clustering, cleaning, file sizing \u2014 stops being an occasional chore and becomes the norm, running constantly alongside ingestion."]}),"\n",(0,s.jsxs)(t.p,{children:["And it must run ",(0,s.jsx)(t.em,{children:"without blocking the writers it serves"}),". If compacting or clustering a table means pausing ingestion, or if maintenance jobs contend with writers as just another optimistic transaction \u2014 conflicting and forcing retries on exactly the hot file groups that change most \u2014 then every maintenance pass reintroduces the latency and cost the pipeline went incremental to eliminate. Hudi builds table services into the storage engine for this reason: compaction, clustering, cleaning, and indexing all ship built-in and run ",(0,s.jsx)(t.a,{href:"/docs/compaction",children:"asynchronously"})," \u2014 in the same process as the writer or as separate jobs \u2014 coordinated through MVCC and ",(0,s.jsx)(t.a,{href:"/docs/concurrency_control",children:"non-blocking concurrency control"})," so writers keep committing while maintenance proceeds in the background."]}),"\n",(0,s.jsx)(t.h2,{id:"incremental-etl-vs-stream-processing",children:"Incremental ETL vs. Stream Processing"}),"\n",(0,s.jsx)(t.p,{children:"Incremental ETL and stream processing share semantics but differ sharply in infrastructure and economics:"}),"\n",(0,s.jsxs)(t.table,{children:[(0,s.jsx)(t.thead,{children:(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.th,{}),(0,s.jsx)(t.th,{children:"Stream processing (Flink, Kafka Streams)"}),(0,s.jsx)(t.th,{children:"Incremental ETL (Hudi on a data lake)"})]})}),(0,s.jsxs)(t.tbody,{children:[(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"Latency"}),(0,s.jsx)(t.td,{children:"Sub-second to seconds"}),(0,s.jsx)(t.td,{children:"Minutes"})]}),(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"Compute model"}),(0,s.jsx)(t.td,{children:"Always-on jobs with managed state"}),(0,s.jsx)(t.td,{children:"Scheduled or continuous mini-batch jobs; state lives in tables"})]}),(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"Storage"}),(0,s.jsx)(t.td,{children:"Event log (Kafka) + state stores + eventual sink"}),(0,s.jsx)(t.td,{children:"One copy: lakehouse tables on cloud object storage"})]}),(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"Reprocessing/backfill"}),(0,s.jsx)(t.td,{children:"Replay the log, rebuild state"}),(0,s.jsx)(t.td,{children:"Re-run the job over a commit range or full table"})]}),(0,s.jsxs)(t.tr,{children:[(0,s.jsx)(t.td,{children:"Query access to intermediate results"}),(0,s.jsx)(t.td,{children:"Requires sinking to another system"}),(0,s.jsx)(t.td,{children:"Every intermediate table is directly queryable"})]})]})]}),"\n",(0,s.jsxs)(t.p,{children:["A useful way to summarize the trade: ",(0,s.jsx)(t.strong,{children:"incremental ETL delivers streaming semantics at minute-level batch economics."})," If a use case genuinely needs sub-second reactions \u2014 fraud blocking, operational alerting \u2014 a stream processor is the right tool. But a large majority of analytics pipelines have freshness requirements in the minutes-to-hour range, where paying for always-on stream infrastructure and a second copy of the data buys nothing. The two also compose rather than compete: Flink writing into Hudi tables gives low-latency ingestion upstream, with cheaper incremental pipelines fanning out downstream."]}),"\n",(0,s.jsx)(t.h2,{id:"a-concrete-pipeline-walkthrough",children:"A Concrete Pipeline Walkthrough"}),"\n",(0,s.jsx)(t.p,{children:"Here is the pattern end to end, using a familiar CDC scenario: an operational database (say, PostgreSQL) whose changes must feed an analytics table."}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Step 1 \u2014 CDC into a bronze table."})," A capture tool such as Debezium streams the database's change log into Kafka, and an ingestion job \u2014 for example ",(0,s.jsx)(t.a,{href:"/docs/hoodie_streaming_ingestion",children:"Hudi Streamer"})," \u2014 continuously upserts those changes into a bronze Hudi table. The bronze table is now a queryable, transactional mirror of the source, and every commit on its timeline is a consumable change point."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Step 2 \u2014 incrementally read the bronze table."})," The silver pipeline wakes up on its schedule (or runs continuously) and pulls only what changed since its last checkpoint:"]}),"\n",(0,s.jsx)(t.pre,{children:(0,s.jsx)(t.code,{className:"language-scala",children:'// Read only the records that changed since the last run\nval ordersDelta = spark.read.format("hudi").\n  option("hoodie.datasource.query.type", "incremental").\n  option("hoodie.datasource.read.begin.instanttime", lastCheckpoint).\n  load(bronzeOrdersPath)\n'})}),"\n",(0,s.jsxs)(t.p,{children:["The same read is available in SQL through the ",(0,s.jsx)(t.code,{children:"hudi_table_changes"})," table-valued function:"]}),"\n",(0,s.jsx)(t.pre,{children:(0,s.jsx)(t.code,{className:"language-sql",children:"SELECT * FROM hudi_table_changes('bronze_orders', 'latest_state', '20260716083000000');\n"})}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Step 3 \u2014 transform and upsert into a silver table."})," The transformation runs over just the delta, and the result is applied as an upsert keyed on the record key:"]}),"\n",(0,s.jsx)(t.pre,{children:(0,s.jsx)(t.code,{className:"language-scala",children:'val silverDelta = ordersDelta.\n  filter(col("order_status") =!= "CANCELLED").\n  withColumn("order_total", col("quantity") * col("unit_price"))\n\nsilverDelta.write.format("hudi").\n  option("hoodie.datasource.write.operation", "upsert").\n  option("hoodie.table.name", "silver_orders").\n  mode("append").\n  save(silverOrdersPath)\n'})}),"\n",(0,s.jsxs)(t.p,{children:["The job then persists the new checkpoint (the latest commit completion time it consumed) for the next run. Because the silver table was written with upserts, it exposes its own change stream \u2014 a gold-layer aggregation job can consume ",(0,s.jsx)(t.code,{children:"silver_orders"})," incrementally in exactly the same way, re-aggregating only the keys whose inputs changed."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.img,{alt:"Incremental ETL: upserts into an upstream table, incrementally consumed to maintain a derived projected table",src:n(86620).A+"",width:"1200",height:"300"}),"\n",(0,s.jsx)("p",{align:"center",children:"Figure: Changes are upserted into an upstream table and incrementally consumed to maintain a derived table"})]}),"\n",(0,s.jsx)(t.p,{children:"One honest caveat: not every transformation is trivially incremental. Simple projections, filters, and enrichments map one-to-one onto deltas. Aggregations require merging new partial results into existing ones, and some full-table operations (percentiles, complex window functions) may still warrant periodic full recomputation. A pragmatic design runs the same logic incrementally for freshness and occasionally in full for correction \u2014 on the same tables and infrastructure."}),"\n",(0,s.jsx)(t.h2,{id:"a-brief-history-pioneered-at-uber",children:"A Brief History: Pioneered at Uber"}),"\n",(0,s.jsxs)(t.p,{children:["Incremental processing on the data lake is not a recent idea bolted onto table formats \u2014 it is the problem Hudi was created to solve. In 2016, Uber's data team faced exactly the trade-off described above: petabyte-scale Hadoop tables that could only be rewritten wholesale, and business use cases (like driver-partner incentives and trip pricing) that needed data in minutes, not hours. The case for a third processing style \u2014 incremental, on top of batch storage \u2014 was laid out in the O'Reilly article ",(0,s.jsx)(t.a,{href:"/blog/2016/08/04/The-Case-for-incremental-processing-on-Hadoop",children:"The Case for Incremental Processing on Hadoop"}),', and Hudi (originally "Hoodie" \u2014 Hadoop Upserts, Deletes and Incrementals) was built at Uber to provide the two missing primitives: upserts and incremental consumption. The project entered the Apache Incubator in 2019 and became a top-level Apache project in 2020; a deeper treatment of the ideas appears in ',(0,s.jsx)(t.a,{href:"/blog/2020/08/18/hudi-incremental-processing-on-data-lakes",children:"Incremental Processing on the Data Lake"}),'. The name itself encodes the pattern \u2014 the "I" in Hudi stands for incrementals.']}),"\n",(0,s.jsx)(t.h2,{id:"conclusion",children:"Conclusion"}),"\n",(0,s.jsx)(t.p,{children:'Incremental ETL replaces "recompute everything, always" with "process what changed, continuously." It requires a storage layer that can serve record-level change streams, absorb upserts and deletes efficiently, and expose reliable commit points to checkpoint against \u2014 the primitives Apache Hudi has provided on data lakes since its inception. The payoff is pipelines whose cost tracks the rate of change in the business rather than the accumulated size of history, with data freshness measured in minutes on the same cheap, open storage batch jobs already use. For most analytics workloads sitting between nightly batch and hard real-time, it is the most economical point on the latency-cost curve.'}),"\n",(0,s.jsx)(t.h2,{id:"faq",children:"FAQ"}),"\n",(0,s.jsx)(a,{heading:null,items:[{question:"What is incremental ETL?",answer:"Incremental ETL is a data pipeline pattern that processes only the records that were inserted, updated, or deleted since the pipeline's last run, instead of re-scanning and rewriting entire tables. Each run consumes a delta from a checkpoint, transforms it, and merges the result into the target table with upserts and deletes. This makes pipeline cost proportional to the volume of change rather than total table size."},{question:"What is the difference between incremental ETL and streaming?",answer:"Both process data as a flow of changes, but stream processors like Apache Flink run always-on jobs with managed state and typically require a separate event log such as Kafka, delivering sub-second latency. Incremental ETL runs as scheduled or continuous mini-batch jobs directly against lakehouse tables on cloud storage, delivering minute-level freshness at much lower infrastructure cost. A common summary is that incremental ETL provides streaming semantics at batch economics."},{question:"How does incremental ETL reduce cost?",answer:"It eliminates repeated scans and rewrites of data that did not change. If a large table receives a small volume of changes between runs, an incremental pipeline reads and processes only that delta instead of the whole table, often reducing data scanned per run by orders of magnitude. Compute clusters also only run for the duration of each small job rather than staying on permanently."},{question:"What does the storage layer need to support incremental ETL?",answer:"Four things: the ability to efficiently retrieve record-level changes between two points in time, support for upserts and deletes so downstream tables can absorb deltas cheaply, an ordered log of commits that consumers can checkpoint against, and table maintenance that runs without blocking writers \u2014 because incremental processing multiplies write frequency, compaction, clustering, and cleaning become continuous background work rather than occasional jobs. Plain Parquet files on object storage provide none of these, which is why incremental ETL depends on a transactional table format. Apache Hudi provides all four through its timeline, indexes, incremental and CDC queries, and built-in asynchronous table services."},{question:"Can every transformation be made incremental?",answer:"No. Projections, filters, enrichments, and key-based joins map naturally onto change streams, and aggregations can be maintained by merging partial results for the affected keys. Some computations, like exact percentiles or complex full-table window functions, are hard to update incrementally, so teams often run those periodically in full while keeping the rest of the pipeline incremental."},{question:"Which Apache Hudi features enable incremental ETL?",answer:"Hudi provides incremental queries that return the latest values of changed records after a given commit, CDC queries that return before and after images of each change, and indexed upsert and delete write operations to apply deltas downstream. Its timeline records every commit with completion times that define exact change windows, and record-level metadata preserves change history across compaction and clustering. Ingestion tools like Hudi Streamer manage incremental checkpoints automatically."}]})]})}function d(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(h,{...e})}):h(e)}},28453:(e,t,n)=>{n.d(t,{R:()=>i,x:()=>o});var a=n(96540);const s={},r=a.createContext(s);function i(e){const t=a.useContext(r);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:i(e.components),a.createElement(r.Provider,{value:t},e.children)}},86620:(e,t,n)=>{n.d(t,{A:()=>a});const a=n.p+"assets/images/image7-0a4cfd0fa02ba7efc07901ae75d1c188.png"},99190:e=>{e.exports=JSON.parse('{"permalink":"/blog/2026/07/16/what-is-incremental-etl-on-a-data-lake","editUrl":"https://github.com/apache/hudi/edit/asf-site/website/blog/blog/2026-07-16-what-is-incremental-etl-on-a-data-lake.md","source":"@site/blog/2026-07-16-what-is-incremental-etl-on-a-data-lake.md","title":"What is Incremental ETL on a Data Lake?","description":"Incremental ETL processes only changed data instead of recomputing entire tables. Learn how it works on a data lake and how Apache Hudi enables it.","date":"2026-07-16T00:00:00.000Z","tags":[{"inline":true,"label":"incremental processing","permalink":"/blog/tags/incremental-processing"},{"inline":true,"label":"etl","permalink":"/blog/tags/etl"},{"inline":true,"label":"streaming","permalink":"/blog/tags/streaming"},{"inline":true,"label":"data lakehouse","permalink":"/blog/tags/data-lakehouse"},{"inline":true,"label":"cdc","permalink":"/blog/tags/cdc"}],"readingTime":13.56,"hasTruncateMarker":false,"authors":[{"name":"Vinoth Chandar","url":"https://www.linkedin.com/in/vinothchandar/","imageURL":"/assets/images/authors/vinoth-chandar.png","key":"vinoth-chandar","page":null}],"frontMatter":{"title":"What is Incremental ETL on a Data Lake?","excerpt":"Incremental ETL is a pipeline pattern that processes only the data that changed since the last run. This post explains how it works, what the storage layer must provide, and how it compares to batch and stream processing.","description":"Incremental ETL processes only changed data instead of recomputing entire tables. Learn how it works on a data lake and how Apache Hudi enables it.","authors":["vinoth-chandar"],"category":"how-to","image":"/assets/images/blog/incr-processing/image7.png","tags":["incremental processing","etl","streaming","data lakehouse","cdc"]},"unlisted":false,"lastUpdatedAt":1784061194000,"prevItem":{"title":"What is ACID on a Data Lake?","permalink":"/blog/2026/07/17/what-is-acid-on-a-data-lake"},"nextItem":{"title":"What is Upsert on a Data Lake?","permalink":"/blog/2026/07/15/what-is-upsert-on-a-data-lake"}}')}}]);